"""Financial Ledger Report - Reflex App with custom serializers."""

from __future__ import annotations

import decimal
import datetime
from typing import Any

import reflex as rx
from rxconfig import config


# ---------------------------------------------------------------------------
# Custom serializers
# ---------------------------------------------------------------------------

def _format_decimal(value: decimal.Decimal) -> str:
    """Format a Decimal as a currency string with 2 decimal places.

    Positive/zero values:  $1,234.56
    Negative values:      -$1,234.56
    """
    if value < 0:
        return f"-${abs(value):,.2f}"
    return f"${value:,.2f}"


@rx.serializer(to=str, overwrite=True)
def serialize_decimal(value: decimal.Decimal) -> str:
    return _format_decimal(value)


@rx.serializer(to=str, overwrite=True)
def serialize_datetime(value: datetime.datetime) -> str:
    return value.strftime("%Y-%m-%d %H:%M")


# ---------------------------------------------------------------------------
# State
# ---------------------------------------------------------------------------

class LedgerEntry(rx.Base):
    """A single ledger entry."""
    description: str
    amount: decimal.Decimal
    timestamp: datetime.datetime


_SEED_ENTRIES: list[LedgerEntry] = [
    LedgerEntry(
        description="Opening balance",
        amount=decimal.Decimal("1000.00"),
        timestamp=datetime.datetime(2024, 1, 1, 9, 0),
    ),
    LedgerEntry(
        description="Grocery store",
        amount=decimal.Decimal("-234.56"),
        timestamp=datetime.datetime(2024, 1, 2, 14, 30),
    ),
    LedgerEntry(
        description="Salary",
        amount=decimal.Decimal("2500.00"),
        timestamp=datetime.datetime(2024, 1, 5, 8, 0),
    ),
    LedgerEntry(
        description="Electric bill",
        amount=decimal.Decimal("-89.99"),
        timestamp=datetime.datetime(2024, 1, 10, 16, 45),
    ),
]


class State(rx.State):
    """The app state."""

    entries: list[LedgerEntry] = _SEED_ENTRIES

    # Input fields
    new_description: str = ""
    new_amount: str = ""

    # Error message for invalid input
    error_message: str = ""

    @rx.var
    def running_balances(self) -> list[decimal.Decimal]:
        """Compute the running balance after each entry."""
        balances: list[decimal.Decimal] = []
        total = decimal.Decimal("0")
        for entry in self.entries:
            total += entry.amount
            balances.append(total)
        return balances

    @rx.var
    def total_credits(self) -> decimal.Decimal:
        """Sum of all positive amounts."""
        return sum(
            (e.amount for e in self.entries if e.amount > 0),
            decimal.Decimal("0"),
        )

    @rx.var
    def total_debits(self) -> decimal.Decimal:
        """Sum of absolute values of all negative amounts (shown positive)."""
        return sum(
            (abs(e.amount) for e in self.entries if e.amount < 0),
            decimal.Decimal("0"),
        )

    @rx.var
    def net_balance(self) -> decimal.Decimal:
        """Net sum of all amounts."""
        return sum(
            (e.amount for e in self.entries),
            decimal.Decimal("0"),
        )

    def add_entry(self):
        """Add a new ledger entry from the input fields."""
        self.error_message = ""

        description = self.new_description.strip()
        if not description:
            self.error_message = "Description cannot be empty."
            return

        amount_str = self.new_amount.strip()
        if not amount_str:
            self.error_message = "Amount cannot be empty."
            return

        try:
            amount = decimal.Decimal(amount_str)
        except decimal.InvalidOperation:
            self.error_message = f"Invalid amount: '{amount_str}'. Please enter a valid number."
            return

        new_entry = LedgerEntry(
            description=description,
            amount=amount,
            timestamp=datetime.datetime.now(),
        )
        self.entries = self.entries + [new_entry]
        self.new_description = ""
        self.new_amount = ""


# ---------------------------------------------------------------------------
# UI helpers
# ---------------------------------------------------------------------------

def _header_cell(label: str, width: str = "auto") -> rx.Component:
    return rx.table.column_header_cell(
        rx.text(label, weight="bold"),
        width=width,
    )


def _ledger_row(entry: LedgerEntry, balance: decimal.Decimal) -> rx.Component:
    """Render a single ledger table row."""
    amount_color = rx.cond(
        entry.amount >= decimal.Decimal("0"),
        "green",
        "red",
    )
    return rx.table.row(
        rx.table.cell(entry.description),
        rx.table.cell(
            rx.text(entry.amount, color=amount_color),
        ),
        rx.table.cell(entry.timestamp),
        rx.table.cell(balance),
    )


def ledger_table() -> rx.Component:
    return rx.table.root(
        rx.table.header(
            rx.table.row(
                _header_cell("Description"),
                _header_cell("Amount"),
                _header_cell("Timestamp"),
                _header_cell("Balance"),
            ),
        ),
        rx.table.body(
            rx.foreach(
                rx.Var.range(State.entries.length()),
                lambda i: _ledger_row(
                    State.entries[i],
                    State.running_balances[i],
                ),
            ),
        ),
        variant="surface",
        width="100%",
    )


def totals_section() -> rx.Component:
    return rx.hstack(
        rx.card(
            rx.vstack(
                rx.text("Total Credits", size="2", color_scheme="gray"),
                rx.text(State.total_credits, size="4", weight="bold", color_scheme="green"),
                align="center",
            ),
            padding="4",
        ),
        rx.card(
            rx.vstack(
                rx.text("Total Debits", size="2", color_scheme="gray"),
                rx.text(State.total_debits, size="4", weight="bold", color_scheme="red"),
                align="center",
            ),
            padding="4",
        ),
        rx.card(
            rx.vstack(
                rx.text("Net Balance", size="2", color_scheme="gray"),
                rx.text(State.net_balance, size="4", weight="bold"),
                align="center",
            ),
            padding="4",
        ),
        spacing="4",
        width="100%",
        justify="center",
    )


def add_entry_form() -> rx.Component:
    return rx.card(
        rx.vstack(
            rx.heading("Add New Entry", size="4"),
            rx.hstack(
                rx.input(
                    placeholder="Description",
                    value=State.new_description,
                    on_change=State.set_new_description,
                    width="300px",
                ),
                rx.input(
                    placeholder="Amount (e.g. 50.25 or -12.00)",
                    value=State.new_amount,
                    on_change=State.set_new_amount,
                    width="220px",
                ),
                rx.button(
                    "Add Entry",
                    on_click=State.add_entry,
                    color_scheme="blue",
                ),
                spacing="3",
                align="end",
            ),
            rx.cond(
                State.error_message != "",
                rx.callout(
                    State.error_message,
                    color_scheme="red",
                    size="1",
                ),
                rx.fragment(),
            ),
            spacing="3",
        ),
        padding="4",
        width="100%",
    )


def index() -> rx.Component:
    return rx.container(
        rx.vstack(
            rx.heading("Financial Ledger", size="8", margin_y="4"),
            ledger_table(),
            rx.divider(),
            totals_section(),
            rx.divider(),
            add_entry_form(),
            spacing="4",
            align="start",
            width="100%",
        ),
        max_width="900px",
        padding="6",
    )


app = rx.App()
app.add_page(index)

